mapper.select:
SELECT su.id AS user_id, GROUP_CONCAT(DISTINCT sr.name SEPARATOR '/') AS role_names FROM system_users su LEFT JOIN system_user_role sur ON su.id = sur.user_id AND sur.deleted = b'0' LEFT JOIN system_role sr ON sur.role_id = sr.id AND sr.status = 0 AND sr.deleted = b'0' WHERE su.deleted = b'0'
AND su.id IN
#{userId}
AND sur.business_id = #{loginBusinessId} AND sr.business_id = #{loginBusinessId}
GROUP BY su.id
